export const countryByCode: Record<string, Country> = Object.fromEntries(countries.map(country => [country.code, country]));
export const countryByNumeric: Record<string, Country> = Object.fromEntries(countries.filter(country => country.numeric).map(country => [country.numeric, country]));

const historicalAliases: Record<string, string[]> = {
  CN: ['China', 'Chinese', '中国', '中國', '清朝', '清政府', '清帝国', '中華民國', '中华民国', 'Qing', 'Peking', 'Beijing', 'Shanghai', 'Hong Kong'],
  US: ['United States', 'American', '美国', '美國', 'Washington', 'New York', 'NASA', 'U.S.', 'USA'],
  GB: ['United Kingdom', 'Britain', 'British', 'England', '英国', '英國', 'London', 'Scotland'],
  FR: ['France', 'French', '法国', '法國', 'Paris', 'Napoleon'],
  DE: ['Germany', 'German', 'Prussia', 'Prussian', '德国', '德國', '普鲁士', '普魯士', 'Berlin'],
  RU: ['Russia', 'Russian', 'Soviet', 'USSR', '俄罗斯', '俄羅斯', '苏联', '蘇聯', 'Moscow'],
  JP: ['Japan', 'Japanese', '日本', 'Tokyo', 'Edo'],
  IN: ['India', 'Indian', '印度', 'New Delhi', 'Bombay'],
  TR: ['Ottoman', 'Turkey', 'Turkish', 'Türkiye', '奥斯曼', '鄂圖曼', '土耳其', 'Constantinople'],
  IT: ['Italy', 'Italian', '意大利', '義大利', 'Rome'],
  KR: ['South Korea', '韩国', '韓國', 'Seoul'],
  KP: ['North Korea', '朝鲜', '朝鮮', 'Pyongyang'],
  ES: ['Spain', 'Spanish', '西班牙', 'Madrid'],
  AT: ['Austria', 'Austrian', '奥地利', '奧地利', 'Vienna', 'Habsburg'],
  AU: ['Australia', 'Australian', '澳大利亚', '澳大利亞', 'Sydney'],
};

const countryMatchers = countries.map(country => {
  const aliases = [...new Set([country.name, country.nameEn, ...country.aliases, ...(historicalAliases[country.code] || [])])];
  const pattern = aliases.filter(alias => alias.length >= 2).map(alias => {
    const escaped = alias.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return /[^\u0000-\u007f]/.test(alias) ? escaped : `(?:^|[^a-z])${escaped}(?=[^a-z]|$)`;
  }).join('|');
  return { code: country.code, matcher: new RegExp(pattern, 'i') };
});

/** Heuristic geographic tags; historical entities use present-day reference countries. */
export function inferCountryCodes(text: string): string[] {
  return countryMatchers.filter(country => country.matcher.test(text)).map(country => country.code);
}
